def nth_bday(start, n):
    d = start
    c = 0
    while c < n:
        d = d + datetime.timedelta(days=1)
        if isb(d):
            c += 1
    return d
def last_bday_of_week(d):
    mon = d - datetime.timedelta(days=d.weekday())
